use std::fs

fn is_int(t: string) -> bool {
    let mut digits = 0
    let mut first = true
    for c in t.chars() {
        if first && c == '-' {
            first = false
            continue
        }
        first = false
        if !c.is_ascii_digit() {
            return false
        }
        digits += 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for t in line.split_whitespace() {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if stack.len() < 2 {
                return "error: underflow"
            }
            let b = stack.pop().unwrap_or(0)
            let a = stack.pop().unwrap_or(0)
            if t == "+" {
                stack.push(a + b)
            } else if t == "-" {
                stack.push(a - b)
            } else if t == "*" {
                stack.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                stack.push(a / b)
            }
        } else if is_int(t) {
            let n = t.parse::<int>().unwrap_or(0)
            stack.push(n)
        } else {
            return "error: token"
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println(eval(line))
    }
}

